QuickSort
 Divide the list into sublists such that every element in the left sublist <= to every element in the right sublist
 Repeat the QuickSort process on the sublists
void QuickSort(vector<char> &A, int left, int right) {
if (left < right) {
Pivot(A, left, right);
int k = Partition(A, left, right);
QuickSort(A, left, k-1);
QuickSort(A, k+1, right);
}

Decomposing Into Sublists
int Partition(vector<char> &A, int left, int right) {
char pivot = A[left];
int i = left;
int j = right+1;
do {
do ++i; while (A[i] < pivot);
do --j; while (A[j] > pivot);
if (i < j) {
Swap(A[i], A[j]);
}
} while (i < j);
Swap(A[j], A[left]);
return j;

